msg.headers = {
    "Content-Type": "application/json",
    "x-api-key": msg.anthropic_key,
    "anthropic-version": "2023-06-01"
};

// Sampling-Parameter (temperature/top_p) werden von Claude Opus 5
// abgelehnt (400) - bewusst weggelassen.
msg.payload = {
    model: "claude-opus-5",
    max_tokens: 16000,
    thinking: { type: "adaptive", display: "summarized" },
    system: msg.system_prompt,
    messages: [
        { role: "user", content: msg.user_prompt }
    ]
};

return msg;

let res = msg.payload;


// Mit aktiviertem adaptive thinking steht vor dem text-Block noch ein
// thinking-Block in res.content - deshalb gezielt den ersten text-Block
// suchen statt content[0] fest anzunehmen.
let raw = res.content.find(b => b.type === "text")?.text;

msg.payload = {
    antwort: raw,
    tokens: res.usage
};
return msg;

// Das Frontend (CAD N'Done, eigener Ursprung) ruft diesen Endpunkt per
// fetch() mit Content-Type: application/json auf - der Browser schickt dem
// eigentlichen POST daher einen OPTIONS-Preflight voraus, der hier
// unabhaengig beantwortet werden muss, sonst blockiert der Browser den POST
// mit einem CORS-Fehler, bevor er ueberhaupt gesendet wird.
msg.statusCode = 204;
msg.headers = {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "POST, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type"
};
return msg;

// Nicht mehr von globalen App-Settings oder einer CMS-Datenbankabfrage
// abhaengig - stattdessen lokale, im Tab selbst einstellbare
// Umgebungsvariablen (siehe Tab-Eigenschaften, Reiter
// "Umgebungsvariablen": AI_PROMPT_ENABLED, AI_SYSTEM_PROMPT).

// Erster Zug: body.message (einzelner String). Ab dem zweiten Zug einer
// agentischen Tool-Use-Konversation schickt das Frontend die komplette
// Historie als body.messages (Array von Anthropic-MessageParam) mit.
const body = msg.req.body ?? {};
const clientMessages = Array.isArray(body.messages) ? body.messages : null;
const message = typeof body.message === "string" ? body.message.trim() : undefined;

if (!clientMessages && !message) {
  msg.statusCode = 400;
  msg.payload = { error: "message oder messages fehlt." };
  return [null, msg];
}

if (!env.get("AI_PROMPT_ENABLED")) {
  msg.statusCode = 400;
  msg.payload = { error: "nicht aktiviert" };
  return [null, msg];
}


// Zeitstempel erzeugen
const now = new Date();
msg.created = now.toISOString(); // → volle UTC-Zeit

msg.message = message;
msg.clientMessages = clientMessages;
msg.tools = Array.isArray(body.tools) ? body.tools : undefined;

msg.locale = body.locale?.trim();
msg.system_prompt = env.get("AI_SYSTEM_PROMPT") || "";

return [msg, null];

msg.headers = {
    "Content-Type": "application/json",
    "x-api-key": msg.anthropic_key,
    "anthropic-version": "2023-06-01"
};

// Ab Zug 2 einer Tool-Use-Konversation schickt das Frontend die komplette
// bisherige Historie mit (inkl. assistant-Zuegen mit tool_use und den
// zugehoerigen tool_result-Antworten) - dann NICHT wieder bei einer
// einzelnen User-Message von vorn anfangen.
const messages = msg.clientMessages ?? [
    { role: "user", content: msg.user_prompt }
];

msg.payload = {
    model: "claude-opus-5",
    max_tokens: 16000,
    // Sampling-Parameter (temperature/top_p) werden von Claude Opus 5
    // abgelehnt (400) - bewusst weggelassen, nicht vergessen wieder
    // einzufuegen.
    thinking: { type: "adaptive", display: "summarized" },
    system: [
        {
            type: "text",
            text: "Antwortsprache: "+msg.locale+". Antworte ausschließlich in dieser Sprache."+msg.system_prompt,
            cache_control: { type: "ephemeral" }
        }
    ],
    messages: messages
};

if (Array.isArray(msg.tools) && msg.tools.length) {
    msg.payload.tools = msg.tools;
}

return msg;

let res = msg.payload;


// Claude-Fehlerantworten (z.B. overloaded_error bei Kapazitaetsengpaessen,
// invalid_request_error, etc.) haben eine eigene Form ({type:"error",
// error:{...}}) statt eines content-Arrays - als eigener Fehler-Statuscode
// durchreichen, sonst haelt das Frontend das faelschlich fuer eine
// erfolgreiche 200er-Antwort und der Fehler kommt im UI nie an.
if (res && res.type === "error") {
  msg.statusCode = 502;
  msg.payload = { error: res.error?.message || "Unbekannter Fehler von Claude" };
  msg.raw = msg.payload.error;
  return msg;
}

// Volle Claude-Antwort unveraendert an den Client durchreichen (statt nur
// den Text zu extrahieren) - der agentische Tool-Use-Loop im Frontend
// braucht tool_use-Bloecke, stop_reason und thinking-Bloecke, nicht nur
// den reinen Antworttext.
msg.statusCode = 200;
// Nur fuers Logging unten: bester verfuegbarer Text-Auszug.
msg.raw = res.content?.find(b => b.type === "text")?.text;

return msg;

const cmsg={
    msgno:1000,
    topic:"GPT RETURN",
    functionName:"GPT RQUEST",
    msg:{
        text:"PAYLOAD",
        payload: {
            text:msg.raw,
            question: msg.message
            }
    }
}
msg=cmsg;


return msg;

const cmsg={
    msgno:1000,
    topic:"GPT ERROR",
    functionName:"GPT REQUEST",
    msg:{
        text:"PAYLOAD",
        payload: {
            text:msg.raw,
            question: msg.message
            }
    }
}
msg=cmsg;


return msg;
